package dev.cosmerearcanists.power;
import com.mojang.authlib.GameProfile;
import dev.cosmerearcanists.*;
import dev.cosmerearcanists.currency.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.Component;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.entity.npc.*;
import net.minecraft.world.item.*;
import net.minecraft.world.item.trading.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.common.util.FakePlayer;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder(CosmereArcanists.MOD_ID)
@PrefixGameTestTemplate(false)
public final class CurrencyGameTests {
    private static FakePlayer player(GameTestHelper h){var p=new FakePlayer(h.getLevel(),new GameProfile(UUID.randomUUID(),"CoinTester"));p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.setPos(Vec3.atCenterOf(h.absolutePos(new BlockPos(1,4,1))));return p;}
    private static SteelProjectile embedded(GameTestHelper h,ItemStack coins){var shot=new SteelProjectile(MetalProjectiles.STEEL.get(),h.getLevel());shot.cargo(coins,Coins.units(coins));var block=h.absolutePos(new BlockPos(4,4,1));h.getLevel().setBlockAndUpdate(block,Blocks.STONE.defaultBlockState());shot.setPos(Vec3.atCenterOf(block.west()));shot.setDeltaMovement(1,0,0);h.getLevel().addFreshEntity(shot);shot.onHit(new BlockHitResult(Vec3.atCenterOf(block).add(-.5,0,0),Direction.WEST,block,false));return shot;}
    private static Villager villager(GameTestHelper h){var v=EntityType.VILLAGER.create(h.getLevel());v.setVillagerData(v.getVillagerData().setProfession(VillagerProfession.FARMER));v.getOffers().clear();return v;}
    @GameTest(template="empty") public static void coinsHaveNoRecipesAndAreMetalWithExplicitMass(GameTestHelper h){
        for(var item:List.of(ModMetals.BOXING.get(),ModMetals.CLIP.get())){var stack=new ItemStack(item,3);h.assertTrue(MetalDetector.detects(h.getLevel().getServer(),stack)&&Math.abs(MetalAmounts.units(h.getLevel().getServer(),stack)-3)<1e-7,"Uncraftable coins are detectable and have explicit nugget mass");h.assertTrue(h.getLevel().getRecipeManager().getRecipes().stream().noneMatch(r->r.value().getResultItem(h.getLevel().registryAccess()).is(item)),"No recipe mints coins");}h.succeed();
    }
    @GameTest(template="empty") public static void firedCoinsEmbedAndSteelUsesThemAsAnchors(GameTestHelper h){
        var p=player(h);PowerAttributes.set(p,"a:steel",1);PowerData.state(p,"a:steel",2);PowerData.reserve(p,"steel",100);PowerData.assignSlot(p,"a:steel",0);PowerService.control(p,new PowerNetwork.Control(2,"",1));var drop=new ItemEntity(h.getLevel(),p.getX(),p.getY(),p.getZ(),new ItemStack(ModMetals.CLIP.get(),4));h.assertTrue(MetalProjectiles.launch(p,drop)!=null,"Held steel launches dropped coins using shared shot strength and damage physics");h.getLevel().getEntitiesOfClass(SteelProjectile.class,p.getBoundingBox().inflate(3)).forEach(SteelProjectile::discard);
        var shot=embedded(h,new ItemStack(ModMetals.CLIP.get(),4));h.assertTrue(shot.embedded()&&shot.fixedMetalAnchor()&&!shot.isRemoved()&&shot.allomanticallyDetectable(h.getLevel().getServer()),"Coin impact keeps a detectable projectile embedded in a surface");var target=MetalTarget.entity(shot,7);var direction=PowerService.anchorDirection(PowerService.chest(p),target.position(h.getLevel(),1),"a:steel");var impulse=PowerService.targetImpulse(p,target,direction,14,"a:steel");h.assertTrue(impulse.dot(direction)>0&&shot.getDeltaMovement().lengthSqr()==0&&shot.embedded(),"Steel pushes the player against the fixed coin instead of ejecting it");PowerService.control(p,new PowerNetwork.Control(2,"",0));shot.discard();h.succeed();
    }
    @GameTest(template="empty") public static void ironTurnsCoinProjectilesIntoExactlyOneReturningItem(GameTestHelper h){
        var p=player(h);var stack=new ItemStack(ModMetals.BOXING.get(),7);stack.set(DataComponents.CUSTOM_NAME,Component.literal("Saved coins"));var shot=embedded(h,stack);var target=MetalTarget.entity(shot,7);var direction=PowerService.anchorDirection(PowerService.chest(p),target.position(h.getLevel(),1),"a:iron");PowerService.targetImpulse(p,target,direction,14,"a:iron");var drops=h.getLevel().getEntitiesOfClass(ItemEntity.class,shot.getBoundingBox().inflate(1),e->e.getItem().is(ModMetals.BOXING.get()));h.assertTrue(shot.isRemoved()&&drops.size()==1&&drops.getFirst().getItem().getCount()==7&&drops.getFirst().getItem().getHoverName().getString().equals("Saved coins"),"Iron atomically returns all coin cargo and components once");var item=drops.getFirst();h.assertTrue(item.getDeltaMovement().dot(p.position().add(0,.5,0).subtract(item.position()))>0,"Returned item flies toward the puller");PowerService.targetImpulse(p,target,direction,14,"a:iron");h.assertTrue(h.getLevel().getEntitiesOfClass(ItemEntity.class,shot.getBoundingBox().inflate(1),e->e.getItem().is(ModMetals.BOXING.get())).size()==1,"Repeated targeting cannot duplicate recovered currency");item.discard();h.succeed();
    }
    @GameTest(template="empty") public static void embeddedCoinPickupHandlesPartialInventoryWithoutDuplication(GameTestHelper h){
        var p=player(h);for(int i=0;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));p.getInventory().setItem(0,new ItemStack(ModMetals.CLIP.get(),60));var shot=embedded(h,new ItemStack(ModMetals.CLIP.get(),10));for(int i=0;i<6;i++)shot.tick();shot.playerTouch(p);h.assertTrue(!shot.isRemoved()&&p.getInventory().getItem(0).getCount()==64,"Only four coins fit; projectile keeps the other six");var item=shot.pullAsItem(p,14);h.assertTrue(item!=null&&item.getItem().getCount()==6&&shot.isRemoved(),"Partial pickup leaves exactly six recoverable coins and correct mass");h.assertTrue(MetalAmounts.units(h.getLevel().getServer(),item.getItem())==6,"Remaining metal quantity follows remaining coin count");item.discard();h.succeed();
    }
    @GameTest(template="empty") public static void embeddedCoinPersistenceAndLifetimeKeepPhysicalCargo(GameTestHelper h){
        var p=player(h);var stack=new ItemStack(ModMetals.CLIP.get(),3);stack.set(DataComponents.CUSTOM_NAME,Component.literal("Persistent clips"));var shot=embedded(h,stack);var saved=new CompoundTag();shot.addAdditionalSaveData(saved);shot.discard();var restored=new SteelProjectile(MetalProjectiles.STEEL.get(),h.getLevel());restored.readAdditionalSaveData(saved);restored.setPos(Vec3.atCenterOf(h.absolutePos(new BlockPos(3,4,1))));h.getLevel().addFreshEntity(restored);h.assertTrue(restored.embedded()&&restored.fixedMetalAnchor(),"Embedded state and anchor survive save/load");var item=restored.pullAsItem(p,14);h.assertTrue(item!=null&&item.getItem().getCount()==3&&item.getItem().getHoverName().getString().equals("Persistent clips"),"Saved projectile retains exact cargo components");item.discard();
        int lifetime=CurrencyConfig.LIFETIME.get();try{CurrencyConfig.LIFETIME.set(100);var expiring=embedded(h,new ItemStack(ModMetals.BOXING.get(),2));for(int i=0;i<101;i++)expiring.tick();h.assertTrue(expiring.isRemoved()&&h.getLevel().getEntitiesOfClass(ItemEntity.class,expiring.getBoundingBox().inflate(1),e->e.getItem().is(ModMetals.BOXING.get())&&e.getItem().getCount()==2).size()==1,"Lifetime recovers currency as an item rather than deleting it");}finally{CurrencyConfig.LIFETIME.set(lifetime);}h.succeed();
    }
    @GameTest(template="empty") public static void coinFeatureGatesAndBrokenSupportAreSafe(GameTestHelper h){
        var p=player(h);var shot=embedded(h,new ItemStack(ModMetals.CLIP.get()));boolean pickup=CurrencyConfig.PICKUP.get(),recall=CurrencyConfig.RECALL.get(),embed=CurrencyConfig.EMBED.get();try{CurrencyConfig.PICKUP.set(false);for(int i=0;i<6;i++)shot.tick();shot.playerTouch(p);h.assertTrue(!shot.isRemoved(),"Disabled pickup leaves saved projectile intact");CurrencyConfig.RECALL.set(false);h.assertTrue(shot.pullAsItem(p,14)==null&&!shot.isRemoved(),"Disabled recall does not consume coins");h.getLevel().setBlockAndUpdate(h.absolutePos(new BlockPos(4,4,1)),Blocks.AIR.defaultBlockState());shot.tick();h.assertTrue(!shot.embedded()&&!shot.isNoGravity(),"Breaking support releases a coin to fall normally");shot.discard();CurrencyConfig.EMBED.set(false);var loose=embedded(h,new ItemStack(ModMetals.CLIP.get(),2));h.assertTrue(loose.isRemoved(),"Disabled embedding uses ordinary shot-to-item recovery");}finally{CurrencyConfig.PICKUP.set(pickup);CurrencyConfig.RECALL.set(recall);CurrencyConfig.EMBED.set(embed);}h.succeed();
    }
    @GameTest(template="empty") public static void scadrianTradesReplaceEmeraldsAndPreserveOfferState(GameTestHelper h){
        var v=villager(h);var output=new ItemStack(Items.DIAMOND_SWORD);output.set(DataComponents.CUSTOM_NAME,Component.literal("Trade blade"));var original=new MerchantOffer(new ItemCost(Items.EMERALD,20),output,12,7,.05f);original.increaseUses();original.addToSpecialPriceDiff(-2);v.getOffers().add(original);h.assertTrue(v.getOffers().getFirst()==original&&original.getBaseCostA().is(Items.EMERALD),"Unmarked Overworld villagers retain normal trades");v.addTag(CurrencyTrades.SCADRIAN);var converted=v.getOffers().getFirst();h.assertTrue(converted.getBaseCostA().is(ModMetals.BOXING.get())&&converted.getBaseCostA().getCount()==2&&converted.getUses()==1&&converted.getMaxUses()==12&&converted.getXp()==7&&converted.getSpecialPriceDiff()==-2&&ItemStack.matches(output,converted.getResult()),"Scadrian conversion preserves uses, maxUses, XP, price state and result components");h.assertTrue(v.getOffers().getFirst()==converted,"Existing converted offers are not converted twice");v.getOffers().add(new MerchantOffer(new ItemCost(Items.WHEAT,20),new ItemStack(Items.EMERALD),16,1,.05f));h.assertTrue(v.getOffers().getLast().getResult().is(ModMetals.CLIP.get())&&v.getOffers().getLast().getResult().getCount()==10,"New selling offers pay clips instead of emeralds");h.succeed();
    }
    @GameTest(template="empty") public static void scadrianPricingAndExchangeUseBothDenominationsWithoutFreeMoney(GameTestHelper h){
        var v=villager(h);var mixed=CurrencyTrades.convert(v,new MerchantOffer(new ItemCost(Items.EMERALD,15),new ItemStack(Items.BREAD),16,1,.05f));h.assertTrue(mixed.getBaseCostA().is(ModMetals.BOXING.get())&&mixed.getBaseCostA().getCount()==1&&mixed.getCostB().is(ModMetals.CLIP.get())&&mixed.getCostB().getCount()==50,"150clip value fits as one boxing and50clips");var two=CurrencyTrades.convert(v,new MerchantOffer(new ItemCost(Items.EMERALD,7),new ItemStack(Items.BREAD),16,1,.05f));h.assertTrue(two.getBaseCostA().getCount()==64&&two.getCostB().getCount()==6,"70clips fit safely across two vanilla input slots");
        v.addTag(CurrencyTrades.SCADRIAN);var offer=v.getOffers().stream().filter(CurrencyTrades::exchange).findFirst().orElseThrow();var a=new ItemStack(ModMetals.CLIP.get(),64);var b=new ItemStack(ModMetals.CLIP.get(),36);h.assertTrue(offer.take(a,b)&&a.isEmpty()&&b.isEmpty()&&offer.getResult().is(ModMetals.BOXING.get())&&offer.getResult().getCount()==1,"Native money-changing consumes100clips for one boxing, without crafting");offer.addToSpecialPriceDiff(-20);v.getOffers();h.assertTrue(offer.getSpecialPriceDiff()==0&&v.getOffers().stream().filter(CurrencyTrades::exchange).count()==1,"Fixed exchange cannot acquire trust/gossip discounts or duplicate itself");h.succeed();
    }
    @GameTest(template="empty") public static void currencyScopeConfigurationAndDisabledTradeDataArePreserved(GameTestHelper h){
        var v=villager(h);var offer=new MerchantOffer(new ItemCost(Items.EMERALD),new ItemStack(Items.BREAD),16,1,.05f);v.getOffers().add(offer);boolean all=CurrencyConfig.ALL_VILLAGERS.get(),trades=CurrencyConfig.TRADES.get();try{CurrencyConfig.TRADES.set(false);v.addTag(CurrencyTrades.SCADRIAN);h.assertTrue(v.getOffers().getFirst()==offer,"Disabled trade conversion leaves original saved offers intact");CurrencyConfig.TRADES.set(true);h.assertTrue(v.getOffers().getFirst().getBaseCostA().is(ModMetals.CLIP.get()),"Re-enabling converts marked villagers");CurrencyConfig.TRADES.set(false);h.assertTrue(v.getOffers().getFirst().getBaseCostA().is(ModMetals.CLIP.get()),"Disabling never deletes existing currency trades");CurrencyConfig.TRADES.set(true);CurrencyConfig.ALL_VILLAGERS.set(true);var world=villager(h);world.getOffers().add(new MerchantOffer(new ItemCost(Items.EMERALD),new ItemStack(Items.BREAD),16,1,.05f));h.assertTrue(world.getOffers().getFirst().getBaseCostA().is(ModMetals.CLIP.get()),"Configuration can opt ordinary dimensions into currency");}finally{CurrencyConfig.ALL_VILLAGERS.set(all);CurrencyConfig.TRADES.set(trades);}h.succeed();
    }
}
